CREATE TABLE IF NOT EXISTS project_capital_readiness (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, legal_ready boolean NOT NULL DEFAULT false, evidence_ready boolean NOT NULL DEFAULT false, valuation_ready boolean NOT NULL DEFAULT false, risk_ready boolean NOT NULL DEFAULT false, economics_ready boolean NOT NULL DEFAULT false, governance_ready boolean NOT NULL DEFAULT false, capital_requirement numeric(20,2), currency text NOT NULL DEFAULT 'NGN', readiness_state text NOT NULL DEFAULT 'not_ready', notes text, assessed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id));